def algorithm(func, dim, lb, ub, budget, rng):
    best_x = np.zeros(dim)
    best_f = float('inf')

    for _ in range(budget):
        x = (ub - lb) * rng.uniform(size=dim) + lb
        f = func(x)

        if f < best_f:
            best_x = x
            best_f = f

    return best_x
